import java.util.*;

public class CF552CVariant3 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int w = sc.nextInt();
        long n = sc.nextLong();

        int k = 0;
        for (int i = 0; w > 2 && i < 21; i++) {
            k = i;
            if (Math.pow(w, i) > 1e9) {
                break;
            }
        }

        HashSet<Long> set = new HashSet<>();
        if (w > 2) {
            long[] pows = new long[k + 1];
            for (int i = 0; i <= k; i++) {
                pows[i] = (long) Math.pow(w, i);
            }
            Deque<long[]> stack = new ArrayDeque<>();
            stack.push(new long[]{0, 0});
            while (!stack.isEmpty()) {
                long[] cur = stack.pop();
                int idx = (int) cur[0];
                long sum = cur[1];
                if (idx > k) {
                    set.add(sum);
                } else {
                    stack.push(new long[]{idx + 1, sum});
                    stack.push(new long[]{idx + 1, sum + pows[idx]});
                }
            }
        }

        boolean bol = (w == 2);
        for (Long i : set) {
            if (i >= n && set.contains(i - n)) {
                bol = true;
                break;
            }
        }

        System.out.println(bol ? "YES" : "NO");
    }
}
